from pathlib import Path

import numpy as np

from export_vhdl import bits
from quantize import hardware_widths

ROOT = Path(__file__).parent.parent
PARAMS = Path(__file__).parent / "out" / "quant_params.npz"
SRC = ROOT / "fpga" / "src"

WEIGHT_BITS = 8
ADDR_BITS = 12
NEURON_BITS = 6
INPUT_BITS = 6
HIDDEN_ADDR_BITS = 5

HEADER = [
    "-- GENERATED by python/export_rom.py from python/out/quant_params.npz.",
    "-- Do not edit by hand: retrain, then rerun the export script.",
]


def ucount(value, width):
    return format(int(value), f"0{width}b")


def row_bits(weights):
    return "".join(bits(w, WEIGHT_BITS) for w in reversed(weights))


def rom_entity(name, addr, addr_bits, out, out_bits, rows):
    lines = [
        "library ieee;",
        "use ieee.std_logic_1164.all;",
        "",
        f"entity {name} is",
        "  port (",
        f"    {addr} : in  std_logic_vector({addr_bits - 1} downto 0);",
        f"    {out} : out std_logic_vector({out_bits - 1} downto 0)",
        "  );",
        f"end entity {name};",
        "",
        f"architecture table of {name} is",
        "begin",
        f"  with {addr} select {out} <=",
    ]
    for a, value, note in rows:
        lines.append(f'    "{value}" when "{ucount(a, addr_bits)}",  -- {note}')
    lines.append(f'    "{"0" * out_bits}" when others;')
    lines += ["end architecture table;", ""]
    return lines


def params_package(p, n_in, n_hidden, n_out, acc_bits, b1q, b2q):
    lines = HEADER + [
        "library ieee;",
        "use ieee.std_logic_1164.all;",
        "",
        "package mlp_params is",
        f"  constant N_IN      : integer := {n_in};",
        f"  constant N_HIDDEN  : integer := {n_hidden};",
        f"  constant N_OUT     : integer := {n_out};",
        f"  constant N_NEURONS : integer := {n_hidden + n_out};",
        "  constant PIXEL_W   : integer := 4;",
        f"  constant WEIGHT_W  : integer := {WEIGHT_BITS};",
        "  constant HIDDEN_W  : integer := 8;",
        f"  constant ACC_W     : integer := {acc_bits};  -- one accumulator width for both layers",
        f"  constant SHIFT1    : integer := {int(p['s1'])};   -- hidden = min(relu(acc) >> SHIFT1, 255)",
        f"  constant ADDR_W    : integer := {ADDR_BITS};  -- weight address (one-MAC core)",
        f"  constant NEURON_W  : integer := {NEURON_BITS};   -- neuron number (one-MAC core)",
        f"  constant INPUT_W   : integer := {INPUT_BITS};   -- input number within a neuron",
        f"  constant HADDR_W   : integer := {HIDDEN_ADDR_BITS};   -- hidden value number",
        "",
        "  -- Loop end points, as bit patterns for the controllers' comparisons",
        f'  constant LAST_PIXEL  : std_logic_vector(INPUT_W-1 downto 0)  := '
        f'"{ucount(n_in - 1, INPUT_BITS)}";  -- {n_in - 1}',
        f'  constant LAST_HIDDEN : std_logic_vector(INPUT_W-1 downto 0)  := '
        f'"{ucount(n_hidden - 1, INPUT_BITS)}";  -- {n_hidden - 1}',
        f'  constant LAST_L1     : std_logic_vector(NEURON_W-1 downto 0) := '
        f'"{ucount(n_hidden - 1, NEURON_BITS)}";  -- last layer-1 neuron ({n_hidden - 1})',
        f'  constant LAST_NEURON : std_logic_vector(NEURON_W-1 downto 0) := '
        f'"{ucount(n_hidden + n_out - 1, NEURON_BITS)}";  -- last neuron ({n_hidden + n_out - 1})',
        "",
        "  -- Biases, sign-extended to ACC_W",
        "  type bias_array is array (natural range <>) of std_logic_vector(ACC_W-1 downto 0);",
        "  constant B1 : bias_array(0 to N_HIDDEN-1) := (",
    ]
    lines += [f'    "{bits(v, acc_bits)}"{"," if j < n_hidden - 1 else " "}  -- neuron {j}: {int(v)}'
              for j, v in enumerate(b1q)]
    lines += ["  );", "  constant B2 : bias_array(0 to N_OUT-1) := ("]
    lines += [f'    "{bits(v, acc_bits)}"{"," if k < n_out - 1 else " "}  -- digit {k}: {int(v)}'
              for k, v in enumerate(b2q)]
    lines += ["  );", "end package mlp_params;", ""]
    return lines


def main():
    p = np.load(PARAMS)
    w1q, b1q, w2q, b2q = p["w1q"], p["b1q"], p["w2q"], p["b2q"]
    n_in, n_hidden = w1q.shape
    n_out = w2q.shape[1]
    acc_bits = hardware_widths(w1q, b1q, w2q, b2q)["acc2_bits_worst_case"]
    SRC.mkdir(parents=True, exist_ok=True)

    (SRC / "mlp_params.vhd").write_text("\n".join(
        ["-- Sizes, loop end points and biases of the digits network (FPGA versions)."]
        + params_package(p, n_in, n_hidden, n_out, acc_bits, b1q, b2q)))

    weight_rows = []
    for j in range(n_hidden):
        for i in range(n_in):
            weight_rows.append((len(weight_rows), bits(w1q[i][j], WEIGHT_BITS),
                                f"L1 neuron {j} pixel {i}: {int(w1q[i][j])}"))
    for k in range(n_out):
        for j in range(n_hidden):
            weight_rows.append((len(weight_rows), bits(w2q[j][k], WEIGHT_BITS),
                                f"L2 digit {k} hidden {j}: {int(w2q[j][k])}"))
    bias_rows = [(j, bits(b1q[j], acc_bits), f"L1 neuron {j}: {int(b1q[j])}")
                 for j in range(n_hidden)]
    bias_rows += [(n_hidden + k, bits(b2q[k], acc_bits), f"L2 digit {k}: {int(b2q[k])}")
                  for k in range(n_out)]
    out = ["-- Weight and bias ROMs for the one-MAC core (mlp_seq)."] + HEADER + [
        f"-- weights_rom: {len(weight_rows)} x {WEIGHT_BITS}-bit weights, in MAC order "
        "(layer 1 neuron by neuron, then layer 2 digit by digit).",
        f"-- bias_rom:    {len(bias_rows)} x {acc_bits}-bit biases "
        f"(0..{n_hidden - 1} layer 1, {n_hidden}..{n_hidden + n_out - 1} layer 2).",
    ]
    out += rom_entity("weights_rom", "addr", ADDR_BITS, "w", WEIGHT_BITS, weight_rows)
    out.append("")
    out += rom_entity("bias_rom", "n", NEURON_BITS, "b", acc_bits, bias_rows)
    (SRC / "weights_rom.vhd").write_text("\n".join(out))

    l1_rows = [(i, row_bits(w1q[i, :]), f"pixel {i}") for i in range(n_in)]
    l2_rows = [(j, row_bits(w2q[j, :]), f"hidden {j}") for j in range(n_hidden)]
    out = ["-- Row ROMs for the 32-MAC core (mlp_par32)."] + HEADER + [
        f"-- rom_l1: pixel i -> {n_hidden} weights W1(0..{n_hidden - 1})(i); "
        "weight of neuron j in bits 8j+7 downto 8j.",
        f"-- rom_l2: hidden j -> {n_out} weights W2(0..{n_out - 1})(j); "
        "weight of digit k in bits 8k+7 downto 8k.",
    ]
    out += rom_entity("rom_l1", "i", INPUT_BITS, "w", n_hidden * WEIGHT_BITS, l1_rows)
    out.append("")
    out += rom_entity("rom_l2", "j", HIDDEN_ADDR_BITS, "w", n_out * WEIGHT_BITS, l2_rows)
    (SRC / "weights_rom32.vhd").write_text("\n".join(out))

    print(f"Wrote {SRC}/mlp_params.vhd, weights_rom.vhd ({len(weight_rows)} weights),"
          f" weights_rom32.vhd ({n_in} + {n_hidden} rows); accumulator {acc_bits} bits")


if __name__ == "__main__":
    main()
